import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.VjMZkWOe.js";const m=JSON.parse('{"title":"Segurança, finalidade e governança","description":"","frontmatter":{},"headers":[],"relativePath":"seguranca.md","filePath":"seguranca.md"}'),r={name:"seguranca.md"};function s(i,t,n,c,p,l){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="seguranca-finalidade-e-governanca" tabindex="-1">Segurança, finalidade e governança <a class="header-anchor" href="#seguranca-finalidade-e-governanca" aria-label="Permalink to &quot;Segurança, finalidade e governança&quot;">​</a></h1><p>Este documento descreve requisitos de proteção. A implantação, políticas e testes reais precisam comprovar cada controle antes do uso com dados pessoais. A governança sensível ainda depende de política aprovada por finalidade; a arquitetura não substitui essa aprovação.</p><h2 id="fronteiras-de-confianca" tabindex="-1">Fronteiras de confiança <a class="header-anchor" href="#fronteiras-de-confianca" aria-label="Permalink to &quot;Fronteiras de confiança&quot;">​</a></h2><p>Entradas HTTP, arquivos e payloads de integrações são não confiáveis. Identidade verificada não concede acesso por si só. A API deriva organização, papel e escopo da associação persistida e reavalia a sessão. O banco aplica RLS com principal transacional e constraints tenant; acesso sensível exige concessão independente.</p><p>Worker não confia em autorização antiga embutida no job. Download não confia em metadados do frontend. Relatórios, busca, agregados e erros não podem contornar as regras de um detalhe. Operadores de infraestrutura possuem privilégios técnicos que exigem contas separadas, acesso emergencial registrado e monitoramento.</p><h2 id="matriz-de-permissoes-proposta" tabindex="-1">Matriz de permissões proposta <a class="header-anchor" href="#matriz-de-permissoes-proposta" aria-label="Permalink to &quot;Matriz de permissões proposta&quot;">​</a></h2><p>Papéis abaixo descrevem responsabilidades funcionais. Nomes concretos e rotas precisam seguir os schemas e políticas implementados; esta tabela não cria um papel novo no backend. &quot;Escopo&quot; significa associação ativa mais carteira/matrícula permitida, e não acesso global na organização.</p><table tabindex="0"><thead><tr><th>Operação</th><th>Administrador da organização</th><th>Gestor</th><th>Mentor</th><th>Equipe de acompanhamento</th><th>Titular futuro</th><th>Worker</th></tr></thead><tbody><tr><td>Estrutura/programas/turmas</td><td>Administrar tenant</td><td>Ler/gerir se delegado</td><td>Ler escopo</td><td>Ler escopo</td><td>—</td><td>IDs do job</td></tr><tr><td>Pessoas e matrículas operacionais</td><td>Conforme política tenant</td><td>Escopo</td><td>Escopo</td><td>Escopo</td><td>Própria, contrato futuro</td><td>Escopo revalidado</td></tr><tr><td>Plano, objetivo e ação</td><td>Conforme delegação</td><td>Escopo</td><td>Escopo</td><td>Escopo</td><td>Própria, contrato futuro</td><td>Operação específica</td></tr><tr><td>Avaliação operacional</td><td>Conforme finalidade</td><td>Escopo</td><td>Escopo</td><td>Escopo</td><td>Própria, contrato futuro</td><td>Operação específica</td></tr><tr><td>Conteúdo pessoal sensível</td><td>Concessão explícita</td><td>Concessão explícita</td><td>Concessão explícita</td><td>Concessão explícita</td><td>Política futura de titular</td><td>Concessão vigente e finalidade</td></tr><tr><td>Conceder/revogar acesso</td><td>Apenas autoridade delegada</td><td>Apenas autoridade delegada</td><td>Não automático</td><td>Não automático</td><td>Consentimento não equivale a conceder papel</td><td>Nunca</td></tr><tr><td>Export padrão</td><td>Autorizado e auditado</td><td>Escopo autorizado</td><td>Se delegado</td><td>Se delegado</td><td>Processo assistido/futuro</td><td>Mesmo escopo do solicitante</td></tr><tr><td>Auditoria</td><td>Administração autorizada</td><td>Se delegado</td><td>—</td><td>—</td><td>Via atendimento, sem dados de terceiros</td><td>Escrever mínimo necessário</td></tr><tr><td>Configurar IAM/secrets</td><td>Papel cloud separado</td><td>—</td><td>—</td><td>—</td><td>—</td><td>Sem poder administrativo</td></tr><tr><td>Executar expurgo/restore</td><td>Papel operacional separado</td><td>Aprovar processo se delegado</td><td>—</td><td>—</td><td>Solicitar</td><td>Job autorizado e auditado</td></tr></tbody></table><p>Administrador não é passe livre sobre relatos pessoais. Toda concessão precisa identificar concessor autorizado, destinatário, organização, matrícula/pilar ou recurso, finalidade, início, expiração e revogação. Revalidar antes de ler, decrypt, download e executar job. Exigir auditar leitura sensível com ID e finalidade, sem relato no evento.</p><h2 id="finalidade-e-classificacao" tabindex="-1">Finalidade e classificação <a class="header-anchor" href="#finalidade-e-classificacao" aria-label="Permalink to &quot;Finalidade e classificação&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Categoria</th><th>Finalidade</th><th>Exposição permitida</th><th>Limite</th></tr></thead><tbody><tr><td>Cadastro mínimo</td><td>Identificar e acompanhar participação</td><td>Equipe com escopo</td><td>Não coletar CPF/foto familiar por conveniência</td></tr><tr><td>Plano e ações</td><td>Acompanhar compromissos acordados</td><td>Responsáveis autorizados</td><td>Evidências podem conter dados pessoais e precisam classificação</td></tr><tr><td>Saúde/família/crença</td><td>Acompanhamento pessoal explicitamente acordado</td><td>Concessão sensível com prazo</td><td>Não usar em risco, vendas, marketing ou IA externa</td></tr><tr><td>Financeiro operacional</td><td>Contrato e renovação autorizados</td><td>Papéis específicos</td><td>Unidade menor e moeda; exposição minimizada</td></tr><tr><td>Consentimento</td><td>Registrar preferências e exercício de direitos</td><td>Operação autorizada</td><td>Não ampliar permissão apenas porque há consentimento</td></tr><tr><td>Auditoria</td><td>Responsabilização e segurança</td><td>Administração limitada</td><td>Sem texto pessoal, tokens ou documentos</td></tr><tr><td>Logs técnicos</td><td>Diagnosticar falhas</td><td>Operação técnica</td><td>IDs pseudônimos; sem corpo sensível, cookie ou bearer</td></tr></tbody></table><p>Status, score, tendência e existência de uma avaliação podem ser sensíveis. Não basta esconder um texto mantendo uma contagem ou aviso &quot;há avaliação restrita&quot;. Retornar projeções equivalentes para quem não tem direito de saber que o registro existe.</p><h2 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ameaça</th><th>Caminho de ataque</th><th>Controle exigido</th><th>Prova necessária</th></tr></thead><tbody><tr><td>BOLA/cross-tenant</td><td>Trocar UUID, filtros ou vínculo de matrícula</td><td>Principal servidor, RLS FORCE, FKs compostas</td><td>Banco real com role runtime e IDs de outro tenant</td></tr><tr><td>Confused deputy</td><td>Job usa ator/tenant escolhidos pelo cliente</td><td>Job com IDs autorizados e revalidação atual</td><td>Revogar associação depois de enfileirar; efeito não acontece</td></tr><tr><td>Escalada por papel</td><td>Payload diz <code>admin</code> ou organiza tenant</td><td>Papel derivado da associação</td><td>Requisição forjada não amplia acesso</td></tr><tr><td>Vazamento de existência</td><td>Busca/timeline/contagem denuncia conteúdo pessoal</td><td>Projeção sem valores/metadados proibidos</td><td>Comparar respostas sem concessão antes/depois de registro sensível</td></tr><tr><td>Revogação tardia</td><td>Token/cache/job continuam acessando</td><td>Sessão persistida e política reavaliada</td><td>Download e job falham após revogar</td></tr><tr><td>Replay/perda de atualização</td><td>Retry duplica ação; cliente antigo sobrescreve</td><td>Idempotência e versão otimista</td><td>Repetição concorrente e versão stale no banco real</td></tr><tr><td>CSRF/roubo de sessão</td><td>Site externo envia mutação web</td><td>Cookie seguro, origem e token CSRF</td><td>Mutação sem prova correta recusada</td></tr><tr><td>Arquivo malicioso</td><td>Tipo forjado, malware, arquivo excessivo</td><td>Quarentena, bytes/tipo real/scan, bucket privado</td><td>Upload hostil não recebe download</td></tr><tr><td>CSV injection</td><td>Export inclui fórmulas do usuário</td><td>Neutralização de células perigosas</td><td>Abrir/inspecionar CSV sintético com prefixos de fórmula</td></tr><tr><td>Decrypt indevido</td><td>IAM técnico ou grant expirado</td><td>KMS mínimo + autorização antes de decrypt</td><td>Expirar finalidade impede leitura e efeito</td></tr><tr><td>Dados ressuscitados</td><td>Restore retorna registros já excluídos</td><td>Marcadores e expurgo antes de reabrir</td><td>Restaurar fixture e reexecutar exclusões</td></tr><tr><td>Exposição de docs</td><td>Pages publica originais, JS ou índice privado</td><td>Build allowlist e origem privada inteira protegida</td><td>Inspeção dos artefatos e canário não listado</td></tr><tr><td>Exfiltração por logs</td><td>Request/error copia relato/token</td><td>Redação e DTOs de erro seguros</td><td>Inspecionar logs de falhas com dados sintéticos</td></tr><tr><td>Disponibilidade</td><td>Consultas amplas, exports e uploads ilimitados</td><td>Limites, cursor, pools e backpressure</td><td>Carga medida e rejeição controlada</td></tr><tr><td>Cadeia de fornecimento</td><td>CI com chave permanente ou imagem mutável</td><td>Federação e digest de imagem</td><td>IAM/workflow e implantação revisados</td></tr></tbody></table><h2 id="retencao-e-expurgo" tabindex="-1">Retenção e expurgo <a class="header-anchor" href="#retencao-e-expurgo" aria-label="Permalink to &quot;Retenção e expurgo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classe</th><th>Política aprovada ou pendência</th><th>Processo</th></tr></thead><tbody><tr><td>Dados operacionais</td><td>Ciclo + 12 meses</td><td>Identificar elegíveis, bloquear acesso, expurgar dependências e arquivos</td></tr><tr><td>Auditoria</td><td>12 meses</td><td>Exclusão programada sem apagar evidência antes do prazo</td></tr><tr><td>Backups</td><td>35 dias</td><td>Política no provedor; verificar expiração e ensaio de restore</td></tr><tr><td>Dados sensíveis</td><td><strong>Aprovação por finalidade pendente antes de uso real</strong></td><td>Prazo mínimo necessário, concessões e retenção separados</td></tr><tr><td>Exports e uploads temporários</td><td>Prazo curto definido no contrato/configuração</td><td>Remover objetos, referências e resultados pendentes</td></tr><tr><td>Marcadores de exclusão</td><td>Devem cobrir toda a janela de restauração</td><td>Reaplicar antes de permitir acesso após restore</td></tr></tbody></table><p>Revogar concessão interrompe acesso, mas não equivale a apagar os dados. Apagar uma matrícula precisa tratar dependências, evidências, resultados de jobs e caches sem atingir outra matrícula da mesma pessoa indevidamente. Obrigação de preservação precisa decisão registrada e acesso bloqueado conforme política.</p><p>Solicitação de titular começa com verificação de identidade e escopo. Export de direitos não revela terceiros. Quando um backup ainda contém dado excluído, ele continua isolado e só pode ser restaurado em ambiente fechado; exclusões são reaplicadas antes de servir requisições. A rotina registra IDs, contagens e resultado, nunca o conteúdo apagado.</p>',18)])])}const g=e(r,[["render",s]]);export{m as __pageData,g as default};
